func BenchmarkEncodeDecodeStatus(b *testing.B) {
	seed := v1.Status[string]{
		Key:         "test_1",
		Name:        "test_2",
		Variant:     v1.Variant("success"),
		Message:     "test_4",
		Description: "test_5",
		Time:        telem.TimeStamp(7),
		Details:     "test_7",
	}
	w := orc.NewWriter(0)
	r := orc.NewReader(nil)
	for b.Loop() {
		w.Reset()
		if err := seed.EncodeOrc(w); err != nil {
			b.Fatal(err)
		}
		var decoded v1.Status[string]
		r.ResetBytes(w.Bytes())
		if err := decoded.DecodeOrc(r); err != nil {
			b.Fatal(err)
		}
	}
}

